--
-- Name: prevent_batchqualitydecision_modification(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prevent_batchqualitydecision_modification() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    RAISE EXCEPTION 'BatchQualityDecision records are immutable audit logs. UPDATE and DELETE operations are prohibited.';
END;
$$;


SET default_tablespace = '';

SET default_table_access_method = heap;

