    output_uom_code_snapshot character varying(20) NOT NULL,
    output_uom_name_snapshot character varying(100) NOT NULL,
    formula_id_snapshot integer NOT NULL,
    formula_code_snapshot character varying(32) NOT NULL,
    formula_name_snapshot character varying(255) NOT NULL,
    formula_revision_number_snapshot integer NOT NULL,
    formula_base_output_quantity_snapshot numeric(14,3) CONSTRAINT batch_plans_batchplan_formula_base_output_quantity_sna_not_null NOT NULL,
