    CONSTRAINT batch_plans_batchplan_formula_id_snapshot_check CHECK ((formula_id_snapshot >= 0)),
    CONSTRAINT batch_plans_batchplan_formula_revision_number_snapshot_check CHECK ((formula_revision_number_snapshot >= 0)),
    CONSTRAINT batch_plans_batchplan_output_uom_id_snapshot_check CHECK ((output_uom_id_snapshot >= 0)),
    CONSTRAINT batch_plans_batchplan_pack_uom_id_snapshot_check CHECK ((pack_uom_id_snapshot >= 0)),
    CONSTRAINT batch_plans_batchplan_product_id_snapshot_check CHECK ((product_id_snapshot >= 0)),
    CONSTRAINT batch_plans_batchplan_source_line_number_snapshot_check CHECK ((source_line_number_snapshot >= 0)),
    CONSTRAINT batch_plans_batchplan_version_check CHECK ((version >= 0))
);


